import React, { useState } from 'react';
import { Menu } from 'antd';
import 'antd/dist/antd.css';
import './Sidebar.css'; // Import your CSS styles

const Sidebar = () => {
  const [activeKey, setActiveKey] = useState(''); // State for active menu item
  const [collapsed, setCollapsed] = useState(true); // State for collapse/expand

  const handleMenuClick = (key) => {
    setActiveKey(key); // Set the clicked menu item as active
  };

  const toggleSidebar = () => {
    setCollapsed(!collapsed); // Toggle sidebar visibility
  };

  return (
    <div className={`menuBar ${collapsed ? 'collapsed' : ''}`}>
      <div className="logo">
        <a href="/">My Logo</a>
      </div>
      <div className="barsMenu" onClick={toggleSidebar}>
        {/* Add icon for the toggle button here */}
        <span>☰</span>
        <span>Menu</span>
      </div>
      <div className="menuCon">
        <Menu
          mode="inline"
          selectedKeys={[activeKey]}
          onClick={({ key }) => handleMenuClick(key)}
        >
          <Menu.Item key="home">Home</Menu.Item>
          <Menu.Item key="about">About</Menu.Item>
          <Menu.SubMenu key="services" title="Services">
            <Menu.Item key="design">Design</Menu.Item>
            <Menu.Item key="development">Development</Menu.Item>
          </Menu.SubMenu>
          <Menu.Item key="contact">Contact</Menu.Item>
        </Menu>
      </div>
    </div>
  );
};

export default Sidebar;
